INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (1, 'Business cyber system(s) that contain sensitive business information, whose exploitation could result in business interruption, economic loss, or theft.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (2, 'Business cyber system(s) that manage supply chain, inventory tracking, ordering and/or shipping, whose exploitation could result in the theft or diversion of property, business interruption, or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (3, 'Business cyber systems that support business functions such as corporate email, payroll, human resources, reporting, scheduling, regulatory and other business-related functions, whose loss or exploitation could result in business interruption or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (4, 'Internet cyber systems that support business functions, such as ordering, customer support, advertising, interactive business functions, and other business-related public interfaces, whose loss or exploitation could result in business interruption or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (5, 'Cyber systems that perform physical security functions (e.g., physical intrusion detection services, access control services, camera services and monitoring software), whose loss or exploitation could result in security vulnerabilities, safety and health issues, damage to equipment or property, business interruption, or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (6, 'Control system(s) that monitor and/or control on-site physical processes or manufacturing services, whose loss or exploitation could result in business interruption, safety and health issues, damage to equipment or property, or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (7, 'Control system(s) that monitor and/or control remote physical processes or services, whose loss or exploitation could result in business interruption, safety and health issues, damage to equipment or property, or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (8, 'Data storage system(s) that provide enterprise, backup, or archiving storage for the organization, whose loss could result in business interruption, theft, or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (9, 'Data storage system(s) that provide enterprise, backup, archiving, or disaster recovery storage for others, whose loss could result in business interruption, theft, or economic loss.')
INSERT INTO [dbo].[CIST_CSI_DEFINING_SYSTEMS] ([Defining_System_Id], [Defining_System]) VALUES (10, 'Other cyber system(s) whose exploitation could result in business interruption, safety and health issues, damage to property, or economic loss.')
