INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5120, 'CT.SB.02', 'Are backups of user-level information contained in the system performed on a defined frequency?', '<div><strong>Control Objective</strong></div><div class="mb-2">a. Conduct backups of user-level information contained in [Assignment: organization-defined system components] [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives];
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5121, 'CT.SB.03', 'Are backups of system-level information contained in the system performed on a defined frequency?', '<div><strong>Control Objective</strong></div><div class="mb-2">a. Conduct backups of user-level information contained in [Assignment: organization-defined system components] [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives];
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5122, 'CT.SB.04', 'Are backups tested on an organization defined frequency basis?', '<div><strong>Control Objective</strong></div><div class="mb-2">Test backup information [Assignment: organization-defined frequency] to verify media reliability and information integrity.</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">Organizations need assurance that backup information can be reliably retrieved. Reliability pertains to the systems and system components where the backup information is stored, the operations used to retrieve the information, and the integrity of the information being retrieved. Independent and specialized tests can be used for each of the aspects of reliability. For example, decrypting and transporting (or transmitting) a random sample of backup files from the alternate storage or backup site and comparing the information to the same information at the primary processing site can provide such assurance.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">CP-4.</div>', '', '', 1, 125, 7, NULL, 1314, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5123, 'CT.SB.05', 'Are backups stored in a location and manner where a significant event in the operational environment would not impact the backups?', '<div><strong>Control Objective</strong></div><div class="mb-2">Transfer system backup information to the alternate storage site [Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives].</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">System backup information can be transferred to alternate storage sites either electronically or by the physical shipment of storage media.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">CP-7, MP-3, MP-4, MP-5.</div>', '', '', 1, 126, 7, NULL, 1314, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5124, 'CT.SB.06', 'Is there a backup processing control center?', '<div><strong>Control Objective</strong></div><div class="mb-2">a. Establish an alternate processing site, including necessary agreements to permit the transfer and resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] when the primary processing capabilities are unavailable;
