INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5131, 'IR.RR.02', 'Is the status of events tracked to resolution?', '<div><strong>Control Objective</strong></div><div class="mb-2">Track and document incidents.</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">Documenting incidents includes maintaining records about each incident, the status of the incident, and other pertinent information necessary for forensics as well as evaluating incident details, trends, and handling. Incident information can be obtained from a variety of sources, including network monitoring, incident reports, incident response teams, user complaints, supply chain partners, audit monitoring, physical access monitoring, and user and administrator reports. IR-4 provides information on the types of incidents that are appropriate for monitoring.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">AU-6, AU-7, IR-4, IR-6, IR-8, PE-6, PM-5, SC-5, SC-7, SI-3, SI-4, SI-7.</div>', '', '', 1, 2, 7, NULL, 1316, 0, '', NULL, NULL, NULL)
