INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5187, 'AC.MD.03.1', 'What kind of encryption do you use for laptops and portable hard drives? (TAB6)', '<div><strong>Control Objective</strong></div><div class="mb-2">Employ [Selection: full-device encryption; container-based encryption] to protect the confidentiality and integrity of information on [Assignment: organization-defined mobile devices].</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">Container-based encryption provides a more fine-grained approach to data and information encryption on mobile devices, including encrypting selected data structures such as files, records, or fields.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">SC-12, SC-13, SC-28.</div>', '', '', 1, 5, 7, 5052, 1279, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5188, 'AC.MD.04.1', 'Describe the usage restrictions and implementation guidance established for organization-controlled (and any other) mobile devices. (LK7)', '<div><strong>Control Objective</strong></div><div class="mb-2">a. Establish configuration requirements, connection requirements, and implementation guidance for organization-controlled mobile devices, to include when such devices are outside of controlled areas; and
