INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5220, 'CM.CM.05.1', 'How do you notify all the potentially impacted parties in change management? (TAB1)', '<div><strong>Control Objective</strong></div><div class="mb-2">Develop, document, and implement a configuration management plan for the system that:
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5221, 'CM.IA.01.1', 'Describe your software management and configuration process. (JEG1)', '<div><strong>Control Objective</strong></div><div class="mb-2">(a) Identify [Assignment: organization-defined software programs not authorized to execute on the system];
(b) Employ an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the system; and
(c) Review and update the list of unauthorized software programs [Assignment: organization-defined frequency].</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">Unauthorized software programs can be limited to specific versions or from a specific source. The concept of prohibiting the execution of unauthorized software may also be applied to user actions, system ports and protocols, IP addresses/ranges, websites, and MAC addresses.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">CM-6, CM-8, CM-10, PL-9, PM-5.</div>', '', '', 1, 2, 7, 5102, 1305, 0, '', NULL, NULL, NULL)
