INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5243, 'LM.AL.03.1', 'Explain how effectively the logs collected support security and incident investigations. (LK16)', '<div><strong>Control Objective</strong></div><div class="mb-2">a. Identify the types of events that the system is capable of logging in support of the audit function: [Assignment: organization-defined event types that the system is capable of logging];
